  </div>

<script>
const POS = ['开心','喜爱','兴奋','自信','期待','满足','感动','平静'];
const NEU = ['思考','惊讶'];
const NEG = ['难过','生气','疲惫','焦虑','孤独','压力'];
const SCORE = {
  '开心':85,'喜爱':82,'兴奋':90,'自信':88,'期待':80,'满足':75,'感动':80,'平静':70,
  '思考':55,'惊讶':60,
  '难过':25,'生气':15,'疲惫':35,'焦虑':20,'孤独':30,'压力':20
};
const QUICK = [
  '今天心情不错','感觉一般般','有点不开心','很累想休息',
  '充满活力','心平气和','坐立不安','若有所思'
];
const QUICK_SCORE = {
  '今天心情不错':78,'感觉一般般':50,'有点不开心':32,'很累想休息':38,
  '充满活力':88,'心平气和':75,'坐立不安':35,'若有所思':65
};

let list = [
  { type:'current', moods:['开心','平静'], text:'专注做完了一段工作，感觉还不错', time:'14:20' },
  { type:'daily', moods:['思考'], text:'在想下周的安排，稍微有点满', time:'11:05' },
  { type:'current', moods:['疲惫','压力'], text:'连着开会有点累，想躺一会儿', time:'09:40' },
  { type:'current', moods:['期待'], text:'晚上约了散步，有点小期待', time:'08:15' }
];
let pick = new Set();
let recType = 'current';
let quickOn = new Set();

function calcScore() {
  if (!list.length) return 0;
  let sum = 0, n = 0;
  for (const it of list) {
    let s = 0, c = 0;
    for (const m of it.moods) if (SCORE[m] != null) { s += SCORE[m]; c++; }
    if (it.text && QUICK_SCORE[it.text]) { s += QUICK_SCORE[it.text]; c++; }
    if (c) sum += s / c; else sum += 50;
    n++;
  }
  return Math.round(sum / n);
}

function scoreMeta(v) {
  if (v >= 80) return { tag:'状态很好', color:'#6BCB77', msg:'正向记录多，节奏很棒。继续保持，也记得适当休息。' };
  if (v >= 60) return { tag:'状态良好', color:'#6BCB77', msg:'最近记录偏正向，保持节奏。压力与疲惫出现时我会提醒你休息。' };
  if (v >= 40) return { tag:'有些波动', color:'#FFD54F', msg:'情绪有起伏很正常。可以走动一下、喝口水，或找我聊聊。' };
  return { tag:'需要关照', color:'#FF6B8A', msg:'负向记录偏多。先休息一下，需要的话我可以陪你慢一点。' };
}

function chipClass(m) {
  if (POS.includes(m)) return 'chip pos';
  if (NEG.includes(m)) return 'chip neg';
  return 'chip';
}

function renderList() {
  const el = document.getElementById('list');
  el.innerHTML = list.map(it => `
    <div class="mood">
      <div class="left">
        <div class="chips">
          <span class="chip">${it.type==='current'?'当前心情':'今日整体'}</span>
          ${it.moods.map(m=>`<span class="${chipClass(m)}">${m}</span>`).join('')}
        </div>
        <div class="txt">${it.text||'（未写描述）'}</div>
      </div>
      <div class="t">${it.time}</div>
    </div>`).join('');
}

function renderScore() {
  const v = calcScore();
  const m = scoreMeta(v);
  document.getElementById('score').textContent = v;
  document.getElementById('ring').style.setProperty('--pct', v);
  document.getElementById('ring').style.setProperty('--sc', m.color);
  const tag = document.getElementById('scoreTag');
  tag.textContent = m.tag;
  tag.style.background = m.color === '#FF6B8A' ? '#3d1a1a' : (m.color==='#FFD54F'?'#3d3a1a':'#1a3d22');
  tag.style.color = m.color;
  document.getElementById('scoreMsg').textContent = m.msg;
  document.getElementById('sToday').textContent = v;
  document.getElementById('barToday').style.background = m.color;
}

function renderMoodPick() {
  const all = [...POS, ...NEU, ...NEG];
  document.getElementById('moods').innerHTML = all.map(m => {
    const on = pick.has(m);
    const cls = POS.includes(m) ? 'pos' : (NEG.includes(m) ? 'neg' : '');
    return `<button data-m="${m}" class="${on?'on '+cls:''}">${m}</button>`;
  }).join('');
}

function renderQuick() {
  document.getElementById('quick').innerHTML = QUICK.map(q =>
    `<button data-q="${q}" class="${quickOn.has(q)?'on':''}">${q}</button>`
  ).join('');
}

function nowTime() {
  const d = new Date();
  return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
}

document.getElementById('btnAdd').onclick = () => {
  pick = new Set(); quickOn = new Set();
  document.getElementById('note').value = '';
  recType = 'current';
  document.querySelectorAll('#segType button').forEach(b => b.classList.toggle('on', b.dataset.v==='current'));
  renderMoodPick(); renderQuick();
  document.getElementById('ov').classList.add('on');
};
document.getElementById('btnCancel').onclick = () => document.getElementById('ov').classList.remove('on');
document.getElementById('ov').onclick = (e) => {
  if (e.target.id === 'ov') document.getElementById('ov').classList.remove('on');
};
document.getElementById('segType').onclick = (e) => {
  const b = e.target.closest('button'); if (!b) return;
  recType = b.dataset.v;
  document.querySelectorAll('#segType button').forEach(x => x.classList.toggle('on', x===b));
};
document.getElementById('moods').onclick = (e) => {
  const b = e.target.closest('button'); if (!b) return;
  const m = b.dataset.m;
  if (pick.has(m)) pick.delete(m); else pick.add(m);
  renderMoodPick();
};
document.getElementById('quick').onclick = (e) => {
  const b = e.target.closest('button'); if (!b) return;
  const q = b.dataset.q;
  quickOn = new Set(); // single pick for simplicity
  quickOn.add(q);
  document.getElementById('note').value = q;
  renderQuick();
};
document.getElementById('btnSave').onclick = () => {
  if (!pick.size) {
    document.getElementById('hintTop').textContent = '先选一个心情标签';
    return;
  }
  const note = document.getElementById('note').value.trim();
  list.unshift({ type: recType, moods:[...pick], text: note, time: nowTime() });
  if (list.length > 12) list.pop();
  document.getElementById('ov').classList.remove('on');
  renderList(); renderScore();
  const t = document.getElementById('toast');
  t.classList.add('on');
  document.getElementById('hintTop').textContent = '已保存，综合分已更新';
  setTimeout(() => t.classList.remove('on'), 1200);
};

renderList(); renderScore(); renderMoodPick(); renderQuick();
</script>
</body>
</html>
```

### 交互流程（确认后写入 LVGL）

```text
健康页（可滑动）
  └─ 底部悬浮「＋ 记录心情」
        └─ 半屏面板
              ├─ 场景：当前心情 / 今日整体
              ├─ 心情标签：多选（开心…压力）
              ├─ 快捷描述：一点即填
              ├─ 输入框：可改一句（板端可先用快捷句）
              └─ 取消 / 保存
                    └─ 插入列表最前 + 重算综合分
```

