<script>
const APs = [
  { ssid: 'Home-5G', sig: 4, lock: true },
  { ssid: 'Home-2.4G', sig: 3, lock: true },
  { ssid: 'Coffee_Free', sig: 2, lock: false },
  { ssid: 'Office-AP', sig: 3, lock: true },
  { ssid: 'MiFi_8821', sig: 1, lock: true },
  { ssid: 'Guest', sig: 2, lock: false },
];
let selected = null;
let connected = null;

const $ = id => document.getElementById(id);
function show(id) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('on'));
  $(id).classList.add('on');
}
function renderList() {
  const el = $('apList');
  el.innerHTML = '';
  APs.forEach((ap, i) => {
    const d = document.createElement('div');
    d.className = 'ap' + (selected === i ? ' sel' : '');
    d.innerHTML = `<span class="name">${ap.ssid}</span>
      <span class="lock">${ap.lock ? '🔒' : ''}</span>
      <span class="sig">${'▮'.repeat(ap.sig)}${'▯'.repeat(4-ap.sig)}</span>`;
    d.onclick = () => { selected = i; renderList(); };
    d.ondblclick = () => startConnect(ap);
    el.appendChild(d);
