    $('curState').style.color = '#6BCB77';
    $('doneIcon').textContent = '✓';
    $('doneIcon').style.color = '#6BCB77';
    $('doneTitle').textContent = '已连接';
    $('doneSub').textContent = 'IP 192.168.1.23 · ' + ap.ssid;
    $('pwInput').value = '';
    show('pDone');
  }, 1600);
}

$('btnScan').onclick = () => {
  $('wifiTip').innerHTML = '<span class="spin"></span> 扫描中…';
  selected = null;
  renderList();
  setTimeout(() => {
    $('wifiTip').textContent = '找到 ' + APs.length + ' 个网络 · 点选后连接';
    renderList();
  }, 900);
};
$('pwBack').onclick = $('pwCancel').onclick = () => { $('kb').classList.remove('on'); show('pWifi'); };
$('pwGo').onclick = () => {
  const ap = APs[selected];
  if (!ap) return;
  if (ap.lock && !$('pwInput').value) { $('pwInput').focus(); return; }
  $('kb').classList.remove('on');
  startConnect(ap);
};
$('doneOk').onclick = () => show('pWifi');

$('kb').onclick = (e) => {
  const b = e.target.closest('button');
  if (!b) return;
  const k = b.dataset.k || b.textContent;
  if (k === 'DEL') $('pwInput').value = $('pwInput').value.slice(0, -1);
  else if (k === 'OK') $('kb').classList.remove('on');
  else if (k.length === 1) $('pwInput').value += k;
};

renderList();
</script>
</body>
</html>
