#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <wireless/wapi.h>
#include <netutils/netlib.h>

int wifi_connect_demo(const char *ifname, const char *ssid, const char *password)
{
    int sock;
    int ret;

    // 1. 创建控制 WiFi 用的 Socket 句柄
    sock = wapi_make_socket();
    if (sock < 0) {
        printf("Error: Failed to create wapi socket\n");
        return -1;
    }

    // 2. 设置工作模式为 STA (Station) 模式
    ret = wapi_set_mode(sock, ifname, WAPI_MODE_IEEE80211_STA);
    if (ret < 0) {
        printf("Error: Failed to set STA mode\n");
        close(sock);
        return -1;
    }

    // 3. 触发周围 WiFi 扫描
    ret = wapi_scan(sock, ifname);
    if (ret < 0) {
        printf("Warning: WiFi scan trigger failed\n");
    } else {
        printf("WiFi scanning...\n");
        sleep(2); // 留出时间让底层驱动收集热点信息
    }

    // 4. 配置加密密码 (WPA/WPA2)
    if (password && password[0] != '\0') {
        ret = wapi_set_psk(sock, ifname, password, WAPI_PASSPHRASE_WPA2);
        if (ret < 0) {
            printf("Error: Failed to set PSK\n");
            close(sock);
            return -1;
        }
    }

    // 5. 设置 ESSID (指定要连接的 WiFi 名称)
    ret = wapi_set_essid(sock, ifname, ssid, WAPI_ESSID_ON);
    if (ret < 0) {
        printf("Error: Failed to set ESSID\n");
        close(sock);
        return -1;
    }

    printf("Connecting to %s...\n", ssid);
    close(sock);

    // 6. 动态申请 IP 地址 (相当于命令行执行 renew wlan0)
    sleep(3); // 等待链路握手完成
    ret = netlib_obtain_ipv4(ifname);
    if (ret < 0) {
        printf("Error: DHCP client failed to get IP\n");
        return -1;
    }

    printf("WiFi connected and IP obtained successfully.\n");
    return 0;
}
