struct sdio_dev_s *sdio_initialize(int sdcno)
{

  struct sdmmc_controller *temp_cont = &sdc_cont[sdcno];
   //初始化sdio协议接口函数
  sdio_dev_initialize(&temp_cont->controller_sunxi_mmc_ops);
